def find_common_values(set1, set2):
    """
    Given two sets, find and return the common values between them.

    Args:
    set1 -- the first set
    set2 -- the second set

    Returns:
    A set containing the common values between set1 and set2.

    Example:
    set1 = {1, 2, 3}
    set2 = {2, 3, 4}
    find_common_values(set1, set2)  # Returns: {2, 3}
    """

### Solution:


    common_values = set()

    for value1 in set1:
        found = False
        iter_set2 = iter(set2)
        while not found:
            try:
                value2 = next(iter_set2)
                if value1 == value2:
                    common_values.add(value1)
                    found = True
            except StopIteration:
                break

    return common_values

